window.docContents[140].resolve({"/UD-III___-storage-and-commands/#Core-C______--UD-III___-storage-and-commands":{"contents":"One typing rule and one evaluation rule per construction of Cmd. The typing rules live in Typing.cmd and the evaluation rules in Eval.cmd. Scope is the restoration of  at block exit, and lifetime is the removal of the local locations from .\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n","context":"Core C++","header":"4. UD III, storage and commands","id":"/UD-III___-storage-and-commands/#Core-C______--UD-III___-storage-and-commands"},"/UD-I___-lexicon-and-grammar/#Core-C______--UD-I___-lexicon-and-grammar":{"contents":"Core C++ has an LL(1) grammar over tokens. Three lexical and syntactic conventions remove the ambiguities of C++. Type identifiers start with an uppercase letter and variable identifiers with a lowercase one, which decides in the lexer whether < opens a template argument or compares. Template instantiation occurs only in type position. Methods are defined inside the class. The lexer is a hand written finite automaton with the longest match rule, and the parser is recursive descent with one function per nonterminal.\n\n\n\n\n\n\n\n\n\n","context":"Core C++","header":"1. UD I, lexicon and grammar","id":"/UD-I___-lexicon-and-grammar/#Core-C______--UD-I___-lexicon-and-grammar"}});